"""Explicit bounded-error tail policy: preserve the exact total and draw iid
ports above the chosen exact-total budget. No failed-trajectory resampling.
"""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
s=(ROOT/'native/gaussian_pnr_number77_v2.cpp').read_text(encoding='utf-8');s=s[s.index('API int number77_sample'):].replace('number77_sample','number77b_sample').replace('int fixed_total,std::uint32_t*','int fixed_total,int exact_total_budget,std::uint32_t*')
s=s.replace('PrecisionGuard guard;need(handle&&output','PrecisionGuard guard;need(exact_total_budget>=0&&exact_total_budget<=498&&exact_total_budget%2==0,"Invalid exact-total budget");need(handle&&output')
s=s.replace('int n=c.model->n,m=c.model->m;','int n=c.model->n,m=c.model->m;number_capacity77(n,exact_total_budget);').replace('stats+8','stats+10').replace('std::array<double,8>','std::array<double,10>').replace('for(int j=0;j<8;++j)','for(int j=0;j<10;++j)').replace('if(j==2||j>=5)','if(j==2||(j>=5&&j<=7))')
old='totals[row]=photons;number_capacity77(n,photons);'
new='''totals[row]=photons;if(photons>std::uint64_t(exact_total_budget)){for(std::uint64_t k=0;k<photons;++k){int mode=categorical(first_cdf,first_total,uniform(detector));++output[std::size_t(row)*m+mode];}trace[0]+=photons;trace[1]+=1;trace[2]=std::max(trace[2],double(photons));trace[3]+=1;trace[4]+=photons;trace[8]+=1;trace[9]+=photons;++completed;continue;}number_capacity77(n,photons);'''
assert old in s;s=s.replace(old,new)
with (ROOT/'native/gaussian_pnr_number77_v3.cpp').open('xb') as f:f.write(('#include "gaussian_pnr_number77_v2.cpp"\n'+s).encode())
s=(ROOT/'src/gbslab/native_number_pnr.py').read_text(encoding='utf-8').replace('NativeNumberPNRSampler','NativeBudgetNumberPNRSampler').replace('number77_sample','number77b_sample').replace('def __init__(self,v,squeezing,library,**kwargs):','def __init__(self,v,squeezing,library,*,exact_total_budget=20,**kwargs):\n        if isinstance(exact_total_budget,bool) or not isinstance(exact_total_budget,int) or not 0<=exact_total_budget<=498 or exact_total_budget%2:raise ValueError("exact_total_budget must be an even integer in [0,498]")\n        self.exact_total_budget=exact_total_budget').replace("'maximum_rank')","'maximum_rank','tail_records','tail_photons')").replace('C.c_int,C.c_int,UP','C.c_int,C.c_int,C.c_int,UP').replace('stats=np.zeros(8)','stats=np.zeros(10)').replace('-1 if fixed_total is None else fixed_total,counts.ctypes','-1 if fixed_total is None else fixed_total,self.exact_total_budget,counts.ctypes').replace('No Gaussian closure or total-count resampling; resource failures are explicit.','No Gaussian closure or resampling. Above the explicit exact-total budget,\nall photons are assigned independently using output row norms.').replace("return dict(counts=counts,total_photons=totals,","return dict(exact_total_budget=self.exact_total_budget,counts=counts,total_photons=totals,")
with (ROOT/'src/gbslab/native_budget_number_pnr.py').open('xb') as f:f.write(s.encode())
